/**
 * traditions.ts — 中国传统条目数据
 *
 * 12 个子分类（与用户的"全传统"板块列表一一对应）：
 *  - history 子分类 33 条（3 综合主题 + 30 朝代，按《半小时漫画中国史》目录）
 *  - geography-regional 子分类 30 条（按"中国人的家"目录）
 *  - 其他 9 子分类各 3-4 条（philosophy / tech 各 4，其余 3）
 *  - 总计 98 条种子数据
 *
 * 字段：
 *  - id: kebab-case slug
 *  - category: TraditionCategory（见下）
 *  - title: 中文标题
 *  - summary: 40-100 字中文摘要
 *  - era: 主要朝代/年代范围（可选）
 *  - figure: 关键人物（可选）
 *  - imageKeyword: Bing 检索关键词（可选）
 *  - imageUrl: 公共版权图片 URL（可选，Wikimedia Commons 优先）
 *  - fullContent?: 详版（100-200 字，弹窗用）
 */

/** 12 个传统子分类（与用户的"全传统"板块列表一一对应） */
export const TRADITION_CATEGORIES = [
  'history',    // 中国人的历史
  'geography-regional', // 中国人的家（地域文化）
  'myth',       // 中国人的神话
  'philosophy', // 中国人的哲学
  'script',     // 中国人的文字
  'literature', // 中国人的文学
  'art',        // 中国人的艺术
  'calendar',   // 中国人的历法和节气
  'ritual',     // 中国人的礼仪与制度
  'food',       // 中国人的衣食
  'housing',    // 中国人的住行
  'tech',       // 中国人的科技
] as const
export type TraditionCategory = typeof TRADITION_CATEGORIES[number]

/** 单条传统条目 */
export interface TraditionItem {
  id: string
  category: TraditionCategory
  title: string
  summary: string           // 50-100 字摘要
  era?: string              // 主要朝代，如 "春秋战国" / "唐宋" / "先秦"
  figure?: string           // 关键人物（可选）
  imageKeyword?: string     // Bing 检索关键词（可选）
  imageUrl?: string         // 公共版权图片 URL（可选，Wikimedia Commons 优先）
  fullContent?: string      // 弹窗正文 100-300 字（可选）

  // === 富内容扩展（可选，老条目可不填） ===
  sections?: RichSection[]
  images?: TraditionImage[]
  timeline?: TimelineEvent[]
  facts?: KeyFact[]
  related?: RelatedItem[]
  source?: string
}

/** 结构化段落 */
export type RichSection =
  | { type: 'paragraph'; heading?: string; body: string }
  | { type: 'callout'; heading?: string; body: string; variant?: 'info' | 'success' | 'warning' | 'quote' }
  | { type: 'list'; heading?: string; items: string[] }
  | { type: 'quote'; heading?: string; text: string; cite?: string }
  | { type: 'table'; heading?: string; headers: string[]; rows: string[][] }

/** 多图画廊 */
export interface TraditionImage {
  url?: string                // 优先 Wikimedia 直链
  imageKeyword: string        // 兜底：bingImage keyword
  caption: string             // 图片说明（用于图注）
  credit?: string             // 来源/作者
}

/** 时间线事件 */
export interface TimelineEvent {
  year: string                // 如 "BC 5000" / "AD 1046" / "上古"
  event: string               // 事件描述
  era?: string                // 朝代补充
}

/** 关键事实（数据卡） */
export interface KeyFact {
  label: string               // "作者" / "年代" / "类别"
  value: string               // "李白" / "AD 712-770"
}

/** 相关条目跳转 */
export interface RelatedItem {
  id: string                  // 对应某条 tradition.id
  title: string
  reason: string              // 为什么相关（用于提示）
}

/** 种子数据：每类 3-4 条，共 41 条（按史实） */
