    source: '《史记·秦本纪》《史记·秦始皇本纪》（西汉·司马迁）·《秦史》（林剑鸣）·《秦国史》（李零）·《秦人崛起研究》（王学理）·《早期秦文化考古》（陕西省考古研究院）',
