    source: '《三国志》（西晋·陈寿）·《资治通鉴·魏纪》（北宋·司马光）·《三国演义》（元末明初·罗贯中）·《后汉书·刘表传》（南朝·范晔）·《三国志集解》（近人·卢弼）',
