    source: '《史记·儒林列传》（西汉·司马迁）·《汉书·董仲舒传》（东汉·班固）·《春秋繁露》（西汉·董仲舒）·《天人三策》（西汉·董仲舒）·《中国儒学史》（汤一介）',
