    source: '《老子注》（魏晋·王弼）·《周易注》（魏晋·王弼）·《周易略例·明象》（魏晋·王弼）·《三国志·钟会传》（西晋·陈寿）·《世说新语》（南朝宋·刘义庆）·《王弼集校释》（楼宇烈）',
