    source: '《传习录》（明·王阳明）·《大学问》（明·王阳明）·《阳明先生文集》（明·王阳明）·《明史·王守仁传》（清·张廷玉）·《王阳明全集》（明·王阳明）·《有无之境》（陈来）',
