    source: '《荀子·解蔽》（战国）·《吕氏春秋·君守》（战国）·《说文解字》（东汉·许慎）·《淮南子·本经训》（西汉·刘安）·《论衡·感类》（东汉·王充）·《中国文字学》（唐兰）',
