    sections: [
      { type: 'paragraph', heading: '为什么荆楚是楚文化的中心？', body: '**荆楚**是**楚文化的发源地**：① 楚是周代最强大的诸侯国之一（BC 1100-AD 223，约 800 年历史）；② **屈原**《离骚》《天问》是中国浪漫主义文学源头；③ **楚庄王**问鼎中原成为春秋霸主；④ **曾侯乙编钟**（1978 年出土）— 中国古代音乐的最高成就；⑤ **楚漆器**是中国工艺美术的代表。' },
      { type: 'callout', heading: '曾侯乙编钟 — 中国古代音乐的最高成就', body: '**曾侯乙编钟**（1978 年湖北随州出土）是**中国最伟大的音乐考古发现**：① 距今 2400 年（战国早期）；② 全套 65 件编钟，总重 2500 kg；③ 每件钟能发两个不同音；④ 音域跨 5 个八度；⑤ 2000 多年前的乐器之王。', variant: 'info' },
      { type: 'paragraph', heading: '为什么湖北是九省通衢？', body: '**湖北**被称为**九省通衢**——武汉位于长江中游 + 京广铁路枢纽；是中国内陆最大的水陆空交通枢纽。' },
      { type: 'list', heading: '荆楚文化的五大符号', items: [
          '**屈原 + 楚辞** — 中国浪漫主义文学源头',
          '**曾侯乙编钟** — 中国古代音乐之王',
          '**楚漆器** — 中国漆器艺术的巅峰',
          '**武汉长江大桥** — 长江第一桥',
          '**赤壁古战场** — 三国文化的见证',
      ] },
      { type: 'paragraph', heading: '为什么赤壁是三国分水岭？', body: '**赤壁之战**（AD 208）是决定三国格局的关键战役：① 曹操率 20 万大军南下；② 孙刘联军在赤壁迎战；③ 周瑜用火攻（黄盖诈降+东风）烧毁曹军战船；④ 曹操北归，**三国鼎立**格局形成。' },
      { type: 'quote', text: '路**漫漫**其修远兮，吾将上下而求索。', cite: '屈原《离骚》' },
    ],
