    sections: [
      { type: 'paragraph', heading: '为什么闽南是海上丝绸之路的起点？', body: '**闽南**（泉州、漳州）是**海上丝绸之路的起点之一**：① 唐宋时期泉州是中国**第一大港**（与广州、宁波并列）；② **马可·波罗**称泉州为"东方第一大港"；③ 元代泉州港与 100+ 个国家有贸易往来；④ **郑和下西洋**从福建长乐起锚。' },
      { type: 'callout', heading: '妈祖信仰 — 中国海洋文化的精神图腾', body: '**妈祖信仰**是中国**海洋文化的核心**：① **林默娘**（960-987），福建莆田湄洲岛人；② 死后被尊为"**妈祖**"（即"娘妈"）；③ 历代皇帝册封 36 次；④ 信众遍及中国沿海+东南亚+全世界（有 5000+ 妈祖庙）。', variant: 'info' },
      { type: 'paragraph', heading: '为什么福建有客家祖地和闽南祖地？', body: '**福建是中国方言最复杂的省份**：① **闽南话**（厦、漳、泉 + 台湾）；② **客家话**（闽西宁化、长汀等）；③ **闽东话**（福州）；④ **莆仙话**（莆田）；⑤ 福建**保留古汉语**最多。' },
      { type: 'list', heading: '闽南文化的五大遗产', items: [
          '**妈祖信仰** — 中国海洋文化的象征',
          '**福建土楼** — 南靖、永定土楼（世界文化遗产）',
          '**闽南建筑** — 泉州开元寺、厦门鼓浪屿',
          '**闽南菜** — 佛跳墙、海蛎煎、沙茶面',
          '**闽南语+歌仔戏** — 跨闽台的语言艺术',
      ] },
      { type: 'paragraph', heading: '为什么福建人漂洋过海成就闽商？', body: '**闽商**是中国**最国际化的商帮**之一：① 福建**多山少田**——海岸线长，迫使人们出海谋生；② 泉州、厦门自古就是对外贸易港口；③ **下南洋**（19-20 世纪）——福建人大量移民东南亚；④ **陈嘉庚**是著名华侨领袖。' },
      { type: 'quote', text: '**下**南洋，闯海外，一片乡心满天涯。', cite: '福建华侨民谚' },
    ],
